PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE springs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  lat REAL NOT NULL,
  lon REAL NOT NULL,
  elevation_ft INTEGER,
  temperature_f INTEGER,
  access_type TEXT NOT NULL,
  development TEXT NOT NULL DEFAULT 'primitive',
  chemistry TEXT,
  state TEXT NOT NULL,
  region TEXT NOT NULL,
  fs_road TEXT,
  description TEXT,
  image_url TEXT,
  source_temperature_c REAL,
  chemistry_source TEXT,
  chemistry_sampled_on TEXT,
  chemistry_level TEXT DEFAULT 'basic',
  chemistry_details TEXT DEFAULT '{}',
  nearby_town TEXT,
  distance_to_town_mi REAL,
  trailhead_lat REAL,
  trailhead_lon REAL,
  fees TEXT,
  fee_amount_usd REAL,
  reservation_required INTEGER DEFAULT 0,
  reservation_url TEXT,
  cell_service TEXT DEFAULT 'unknown',
  seasonal_open TEXT,
  seasonal_close TEXT,
  seasonal_notes TEXT,
  dog_policy TEXT DEFAULT 'unknown',
  clothing_policy TEXT DEFAULT 'unknown',
  ada_accessible INTEGER DEFAULT 0,
  pool_count INTEGER,
  water_flow TEXT DEFAULT 'unknown',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
, vehicle_requirement TEXT DEFAULT 'any', permit_types TEXT DEFAULT '[]', crowding_pattern TEXT DEFAULT 'unknown', ferry_dependent INTEGER DEFAULT 0, ferry_route TEXT, winter_access_notes TEXT, nwac_zone TEXT);
CREATE TABLE spring_images (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  spring_slug TEXT NOT NULL,
  source TEXT NOT NULL,            -- wikimedia_commons | wikipedia | wikidata | flickr | openverse | google_places | operator
  image_url TEXT NOT NULL,         -- canonical full-size URL
  thumb_url TEXT,                  -- smaller preview URL when available
  license_code TEXT,               -- e.g. 'CC BY 2.0', 'CC0', 'PDM', 'Public domain'
  license_url TEXT,
  attribution TEXT,                -- creator / author
  source_url TEXT,                 -- foreign landing page (Commons/Flickr/Openverse page)
  provider_image_id TEXT,          -- dedup key: Commons pageid, Flickr photo id, Openverse uuid
  width INTEGER,
  height INTEGER,
  is_primary INTEGER DEFAULT 0,
  rank INTEGER DEFAULT 0,          -- within-spring ordering for a source
  captured_at TEXT,
  last_fetched TEXT DEFAULT (datetime('now'))
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_springs_slug ON springs(slug);
CREATE INDEX idx_springs_state ON springs(state);
CREATE INDEX idx_springs_region ON springs(region);
CREATE INDEX idx_springs_access_type ON springs(access_type);
CREATE INDEX idx_springs_development ON springs(development);
CREATE INDEX idx_springs_temperature ON springs(temperature_f);
CREATE INDEX idx_springs_vehicle ON springs(vehicle_requirement);
CREATE INDEX idx_springs_ferry ON springs(ferry_dependent);
CREATE INDEX idx_springs_crowding ON springs(crowding_pattern);
CREATE INDEX idx_spring_images_slug ON spring_images(spring_slug);
CREATE INDEX idx_spring_images_slug_primary ON spring_images(spring_slug, is_primary);
CREATE UNIQUE INDEX uq_spring_images_provider_id ON spring_images(source, provider_image_id);
CREATE UNIQUE INDEX uq_spring_images_url ON spring_images(spring_slug, image_url);
